-- Studio V0.3 SQLite DO optional v3 security migration; STAGING ONLY. Not wired to production.
CREATE TRIGGER IF NOT EXISTS v03_v3_terminal_jobs_all_columns BEFORE UPDATE ON jobs WHEN OLD.state IN ('COMPLETED','FAILED') BEGIN SELECT RAISE(ABORT,'TERMINAL_JOB_IMMUTABLE'); END;
CREATE TRIGGER IF NOT EXISTS v03_v3_assets_never_reassign BEFORE UPDATE OF job_id ON assets WHEN NEW.job_id IS NOT OLD.job_id BEGIN SELECT RAISE(ABORT,'ASSET_JOB_REASSIGNMENT_DENIED'); END;
CREATE TRIGGER IF NOT EXISTS v03_v3_terminal_asset_update BEFORE UPDATE ON assets WHEN (SELECT state FROM jobs WHERE id=OLD.job_id) IN ('COMPLETED','FAILED') BEGIN SELECT RAISE(ABORT,'COMPLETED_ASSET_IMMUTABLE'); END;
CREATE TRIGGER IF NOT EXISTS v03_v3_terminal_asset_delete BEFORE DELETE ON assets WHEN (SELECT state FROM jobs WHERE id=OLD.job_id) IN ('COMPLETED','FAILED') BEGIN SELECT RAISE(ABORT,'COMPLETED_ASSET_IMMUTABLE'); END;
